3	/**
4	 * Thrown by {@code CheckOwnerDailyLimit} when a create-owner request arrives after {@code 100} or
5	 * more owners have already been registered today (by {@code registrationDate}). Handled by
6	 * {@link OwnerDailyLimitExceptionHandler}, which responds 429.
7	 */
8	public class OwnerDailyLimitException extends Exception {
9	
10	    public OwnerDailyLimitException(int count) {
11	        super("Daily owner registration limit reached (" + count + " owners created today)");
12	    }
13	}
